CREATE TABLE IF NOT EXISTS users (id VARCHAR(40) PRIMARY KEY,name VARCHAR(80) NOT NULL,email VARCHAR(254) NOT NULL,password_hash VARCHAR(255) NOT NULL,created_at DATETIME(6) NOT NULL,UNIQUE KEY uk_users_email(email)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE IF NOT EXISTS user_sessions (token_hash CHAR(64) PRIMARY KEY,user_id VARCHAR(40) NOT NULL,expires_at DATETIME(6) NOT NULL,created_at DATETIME(6) NOT NULL,CONSTRAINT fk_sessions_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,INDEX idx_sessions_expiry(expires_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
